    output counting,
    output done
);

    typedef enum logic [2:0] {
        S0,
        S1,
        S2,
        S3,
        SHIFT,
        COUNT,
        DONE
    } state_t;

    state_t state, next_state;
    logic [2:0] shift_cnt; // counts cycles in SHIFT state (0-4)

    // State register
    always_ff @(posedge clk) begin
        if (reset) begin
            state <= S0;
            shift_cnt <= 0;
        end else begin
            state <= next_state;
            // Update shift counter only when in SHIFT state
            if (state == SHIFT) begin
                if (shift_cnt < 3'd4) begin
                    shift_cnt <= shift_cnt + 1'b1;
                end else begin
                    shift_cnt <= 0; // reset for safety
                end
            end else begin
                shift_cnt <= 0;
            end
        end
    end

    // Next state logic
    always_comb begin
        next_state = state; // default to hold state

        unique case (state)
            S0: begin
                if (data == 1'b1)
                    next_state = S1;
                else
                    next_state = S0;
            end
            S1: begin
                if (data == 1'b1)
                    next_state = S2;
                else
                    next_state = S0;
            end
            S2: begin
                if (data == 1'b0)
                    next_state = S3;
                else // data == 1'b1
                    next_state = S2;
            end
            S3: begin
                if (data == 1'b1)
                    next_state = SHIFT;
                else
                    next_state = S0;
            end
            SHIFT: begin
                if (shift_cnt < 3'd4)
                    next_state = SHIFT;
                else
                    next_state = COUNT;
            end
            COUNT: begin
