module TopModule (
    input  clk,
    input  in,
    input  reset,
    output reg [7:0] out_byte,
    output reg done
);

    // State definitions
    typedef enum logic [3:0] {
        IDLE   = 4'b0000,
        START  = 4'b0001,
        DATA0  = 4'b0010,
        DATA1  = 4'b0011,
        DATA2  = 4'b0100,
        DATA3  = 4'b0101,
        DATA4  = 4'b0110,
        DATA5  = 4'b0111,
        DATA6  = 4'b1000,
        DATA7  = 4'b1001,
        STOP   = 4'b1010
    } state_t;

    state_t state, next_state;
    reg [2:0] bit_count; // Counts received data bits (0 to 7)
    reg [7:0] shift_reg; // Shift register to accumulate data bits (LSB first)

    // State register
    always @(posedge clk) begin
        if (reset) begin
            state        <= IDLE;
            bit_count    <= 3'b000;
            shift_reg    <= 8'b0;
            out_byte     <= 8'b0;
            done         <= 1'b0;
        end else begin
            state        <= next_state;
            // Update bit_count and shift_reg based on current state
            case (state)
                START: begin
                    bit_count    <= 3'b000;
                    shift_reg    <= 8'b0;
                end
                DATA0, DATA1, DATA2, DATA3, DATA4, DATA5, DATA6, DATA7: begin
                    // Shift in the current bit at position bit_count (LSB first)
                    shift_reg    <= shift_reg | (in << bit_count);
                    bit_count    <= bit_count + 3'b001;
                end
                default: begin
                    // Hold values in other states
                    bit_count    <= bit_count;
                    shift_reg    <= shift_reg;
                end
            endcase
            // Update output registers
            out_byte     <= shift_reg;
            done         <= (state == STOP && in); // Pulse when correct stop bit is seen
        end
    end

    // Next state logic
    always @* begin
        case (state)
            IDLE: begin
                if (in == 1'b0) // Start bit detected
                    next_state = START;
                else
                    next_state = IDLE;
            end
            START: begin
                next_state = DATA0;
            end
            DATA0: begin
                next_state = DATA1;
            end
            DATA1: begin
                next_state = DATA2;
            end
            DATA2: begin
                next_state = DATA3;
            end
            DATA3: begin
                next_state = DATA4;
            end
            DATA4: begin
                next_state = DATA5;
            end
            DATA5: begin
                next_state = DATA6;
            end
            DATA6: begin
                next_state = DATA7;
            end
            DATA7: begin
                next_state = STOP;
            end
            STOP: begin
                if (in == 1'b1) // Correct stop bit
                    next_state = IDLE;
                else
                    next_state = STOP; // Wait for stop bit
            end
            default: begin
                next_state = IDLE;
            end
        endcase
    end

endmodule
